  }

  .principles {
    padding-block: 3.5rem;
  }

  .section-heading,
  .principles__grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    gap: 1rem;
  }

  h2 {
    font-size: 2rem;
  }

  .principles__grid {
    gap: 0;
  }

  .principles article {
    display: grid;
    grid-template-columns: 2.5rem minmax(0, 1fr);
    column-gap: 0.75rem;
    padding-block: 1.5rem;
    border-bottom: 1px solid var(--colour-border);
  }

  .principle-number {
    grid-row: 1 / span 2;
    margin: 0;
  }

  .principles article p:last-child {
    max-width: none;
  }

  .site-footer__inner {
    min-height: 9rem;
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 1rem;
  }

  .browse-page {
