    (signal: AbortSignal) => publicReadApi.getCompetition(competitionId, signal),
    [competitionId],
  );

  return (
    <DetailState
      label="Competition"
      load={load}
      render={({ data: competition }) => {
        const id = encodeURIComponent(competition.competitionId);
        return (
          <DetailLayout
            backLabel="competitions"
