            eyebrow="Participant"
            title={participant.displayName}
          >
            <RecordFacts>
              <RecordFact label="Participant ID" value={participant.participantId} />
            </RecordFacts>
          </DetailLayout>
        );
      }}
      requestKey={participantId}
    />
