import { type ReactNode, useCallback, useId, useMemo, useState } from 'react';

import type { CollectionResponse } from '../../api/public-read';
import { usePublicData } from './usePublicData';

interface RelatedCollectionProps<Resource> {
  emptyMessage: string;
  filters: URLSearchParams;
  load(search: string, signal: AbortSignal): Promise<CollectionResponse<Resource>>;
  renderRecords(resources: Resource[]): ReactNode;
  resourceLabel: string;
  title: string;
}

export function RelatedCollection<Resource>({
  emptyMessage,
  filters,
  load,
  renderRecords,
  resourceLabel,
  title,
}: RelatedCollectionProps<Resource>) {
  const headingId = useId();
  const [cursor, setCursor] = useState<string | null>(null);
  const search = useMemo(() => {
    const params = new URLSearchParams(filters);
    params.set('limit', '10');
    if (cursor) {
      params.set('cursor', cursor);
    }
    return `?${params.toString()}`;
  }, [cursor, filters]);
  const loadRecords = useCallback((signal: AbortSignal) => load(search, signal), [load, search]);
  const state = usePublicData(loadRecords, search);

  return (
    <section aria-labelledby={headingId} className="related-collection">
      <div className="results-heading">
        <h2 id={headingId}>{title}</h2>
        {state.status === 'ready' ? (
          <p aria-live="polite">
            {state.data.data.length} {state.data.data.length === 1 ? 'record' : 'records'} on this
            page
          </p>
        ) : null}
      </div>

      {state.status === 'loading' ? (
        <div className="state-message" role="status">
          <h3>Loading {resourceLabel}</h3>
          <p>The related published records are being requested.</p>
        </div>
      ) : null}

      {state.status === 'error' ? (
        <div className="state-message state-message--error" role="alert">
          <h3>{title} could not be loaded</h3>
          <p>Published {resourceLabel} could not be requested. Try this section again.</p>
          <button
            aria-label={`Retry ${resourceLabel}`}
            className="button button--secondary"
            onClick={state.reload}
            type="button"
          >
            Try again
          </button>
        </div>
      ) : null}

      {state.status === 'ready' && state.data.data.length === 0 ? (
        <div className="state-message" role="status">
          <h3>No {resourceLabel} found</h3>
          <p>{emptyMessage}</p>
        </div>
      ) : null}

      {state.status === 'ready' && state.data.data.length > 0 ? (
        <>
          {renderRecords(state.data.data)}
          {state.data.pagination.nextCursor ? (
            <nav aria-label={`${title} pagination`} className="pagination">
              <button
                aria-label={`Next ${resourceLabel} page`}
                className="button button--secondary"
                onClick={() => setCursor(state.data.pagination.nextCursor)}
                type="button"
              >
                Next page
              </button>
            </nav>
          ) : (
            <p className="pagination__end">End of published results</p>
          )}
        </>
      ) : null}
    </section>
  );
}
  }

  if (state.status === 'error') {
    return (
      <div className="detail-page content-boundary">
        <DetailError error={state.error} label={label} reload={state.reload} />
      </div>
    );
  }

  return render(state.data);
}

export function CompetitionDetailPage() {
  const { competitionId = '' } = useParams();
  const load = useCallback(
    (signal: AbortSignal) => publicReadApi.getCompetition(competitionId, signal),
    [competitionId],
  );

  return (
    <DetailState
      label="Competition"
      load={load}
      render={({ data: competition }) => {
        return (
          <DetailLayout
            backLabel="competitions"
            backTo="/competitions"
            eyebrow="Competition"
            title={competition.name}
          >
            <RelatedCollection
              emptyMessage="No published seasons are available for this competition."
              filters={relatedFilters('competitionId', competition.competitionId)}
              load={publicReadApi.listSeasons}
              renderRecords={(seasons) => <SeasonRecords seasons={seasons} />}
              resourceLabel="seasons"
              title="Seasons"
            />
            <RelatedCollection
              emptyMessage="No published fixtures are available for this competition."
              filters={relatedFilters('competitionId', competition.competitionId)}
              load={publicReadApi.listFixtures}
              renderRecords={(fixtures) => <CompetitionFixtureRecords fixtures={fixtures} />}
              resourceLabel="fixtures"
              title="Fixtures by season"
            />
            <RelatedCollection
              emptyMessage="No published teams are available for this competition."
              filters={relatedFilters('competitionId', competition.competitionId)}
              load={publicReadApi.listCompetitors}
              renderRecords={(teams) => <TeamRecords teams={teams} />}
              resourceLabel="teams"
              title="Teams"
            />
          </DetailLayout>
        );
      }}
      requestKey={competitionId}
    />
  );
}

export function SeasonDetailPage() {
  const { seasonId = '' } = useParams();
  const load = useCallback(
    (signal: AbortSignal) => publicReadApi.getSeason(seasonId, signal),
    [seasonId],
  );

  return (
    <DetailState
      label="Season"
      load={load}
      render={({ data: season }) => {
        return (
          <DetailLayout
            backLabel="seasons"
            backTo="/seasons"
            eyebrow={season.competitionName}
            title={season.label}
          >
            <RecordFacts>
              <RecordFact
                label="Competition"
                value={
                  <Link to={`/competitions/${encodeURIComponent(season.competitionId)}`}>
                    {season.competitionName}
                  </Link>
                }
              />
            </RecordFacts>
            <RelatedCollection
              emptyMessage="No published fixtures are available for this season."
              filters={relatedFilters('seasonId', season.seasonId)}
              load={publicReadApi.listFixtures}
              renderRecords={(fixtures) => <FixtureRecords fixtures={fixtures} />}
              resourceLabel="fixtures"
              title="Fixtures"
            />
            <RelatedCollection
              emptyMessage="No published teams are available for this season."
              filters={relatedFilters('seasonId', season.seasonId)}
              load={publicReadApi.listCompetitors}
              renderRecords={(teams) => <TeamRecords teams={teams} />}
              resourceLabel="teams"
              title="Teams"
            />
          </DetailLayout>
        );
      }}
      requestKey={seasonId}
    />
  );
}

export function FixtureDetailPage() {
  const { fixtureId = '' } = useParams();
  const load = useCallback(
    (signal: AbortSignal) => publicReadApi.getFixture(fixtureId, signal),
    [fixtureId],
  );

  return (
    <DetailState
      label="Fixture"
      load={load}
      render={({ data: fixture }) => {
        return (
          <DetailLayout
            backLabel="fixtures"
            backTo="/fixtures"
            eyebrow="Fixture overview"
            title={fixtureTitle(fixture)}
          >
            <RecordFacts>
              <RecordFact
                label="Competition"
                value={
                  fixture.competitionId && fixture.competitionName ? (
                    <Link to={`/competitions/${encodeURIComponent(fixture.competitionId)}`}>
                      {fixture.competitionName}
                    </Link>
                  ) : (
                    'Competition name unavailable'
                  )
                }
              />
              <RecordFact
                label="Season"
                value={
                  fixture.seasonId ? (
                    <Link to={`/seasons/${encodeURIComponent(fixture.seasonId)}`}>
                      {fixture.seasonLabel}
                    </Link>
                  ) : (
                    fixture.seasonLabel
                  )
                }
              />
              <RecordFact
                label="Teams"
                value={
                  fixture.competitors.length > 0 ? (
                    <span className="record-fact-links">
                      {fixture.competitors.map((team) => (
                        <Link
                          key={team.competitorId}
                          to={`/competitors/${encodeURIComponent(team.competitorId)}`}
                        >
                          {team.name}
                        </Link>
                      ))}
                    </span>
                  ) : (
                    'Team names unavailable'
                  )
                }
              />
