                inningsOrdinal: 0,
                sequenceNumber: 1,
                strikerParticipantId: 'striker-1',
                bowlerParticipantId: 'bowler-1',
                runs: { offBat: 4, extras: 1, total: 5 },
                extras: {
                  wides: 1,
                  noBalls: null,
                  byes: null,
                  legByes: null,
                  penalty: null,
                },
                nonBoundary: false,
                bowlerWickets: 0,
