      heading: 'A Player',
    },
  ])('opens $linkName from its public collection', async (example) => {
    vi.stubGlobal(
      'fetch',
      vi
        .fn()
        .mockImplementation((url: string) =>
          Promise.resolve(
            url.endsWith(example.detailPath)
              ? response(200, { data: example.detailRecord })
              : collection([example.listRecord]),
          ),
